CREATE OR ALTER PROCEDURE [dbo].[uspGoodsReceiptLine_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @GoodsReceiptId UNIQUEIDENTIFIER = NULL
	, @IngredientId UNIQUEIDENTIFIER = NULL
	, @LotId UNIQUEIDENTIFIER = NULL
	, @UnitId UNIQUEIDENTIFIER = NULL
	, @ReceivedQuantity DECIMAL(18,4) = NULL
	, @AcceptedQuantity DECIMAL(18,4) = NULL
	, @RejectedQuantity DECIMAL(18,4) = NULL
	, @LotNumber NVARCHAR(MAX) = NULL
	, @ManufactureDate DATETIME2 = NULL
	, @ExpiryDate DATETIME2 = NULL
	, @QualityStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[GoodsReceiptId]
			, t.[IngredientId]
			, t.[Quantity]
			, t.[UnitCost]
			, t.[LotId]
			, t.[ReceivedQuantity]
			, t.[AcceptedQuantity]
			, t.[RejectedQuantity]
			, t.[UnitId]
			, t.[LotNumber]
			, t.[ManufactureDate]
			, t.[ExpiryDate]
			, t.[QualityStatus]
			, t.[CreatedDate]
		FROM [dbo].[GoodsReceiptLine] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[LotNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@GoodsReceiptId IS NULL OR t.[GoodsReceiptId] = @GoodsReceiptId)
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (@LotId IS NULL OR t.[LotId] = @LotId)
			AND (@UnitId IS NULL OR t.[UnitId] = @UnitId)
			AND (@ReceivedQuantity IS NULL OR t.[ReceivedQuantity] = @ReceivedQuantity)
			AND (@AcceptedQuantity IS NULL OR t.[AcceptedQuantity] = @AcceptedQuantity)
			AND (@RejectedQuantity IS NULL OR t.[RejectedQuantity] = @RejectedQuantity)
			AND (ISNULL(@LotNumber, '') = '' OR t.[LotNumber] LIKE CONCAT('%', @LotNumber, '%'))
			AND (@ManufactureDate IS NULL OR t.[ManufactureDate] = @ManufactureDate)
			AND (@ExpiryDate IS NULL OR t.[ExpiryDate] = @ExpiryDate)
			AND (ISNULL(@QualityStatus, '') = '' OR t.[QualityStatus] LIKE CONCAT('%', @QualityStatus, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'goodsReceiptId' THEN r.[GoodsReceiptId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'goodsReceiptId' THEN r.[GoodsReceiptId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitCost' THEN r.[UnitCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitCost' THEN r.[UnitCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lotId' THEN r.[LotId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lotId' THEN r.[LotId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receivedQuantity' THEN r.[ReceivedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receivedQuantity' THEN r.[ReceivedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitId' THEN r.[UnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitId' THEN r.[UnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lotNumber' THEN r.[LotNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lotNumber' THEN r.[LotNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'manufactureDate' THEN r.[ManufactureDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'manufactureDate' THEN r.[ManufactureDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expiryDate' THEN r.[ExpiryDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expiryDate' THEN r.[ExpiryDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
